  }
  run();
  return () => { ignore = true; };
}, []);

function Tooltip({ targetRect, children }) {
  const ref = useRef(null);
  const [top, setTop] = useState(0);
  useLayoutEffect(() => {
    const { height } = ref.current.getBoundingClientRect();
    setTop(targetRect.top - height);   // applied before paint: no flicker
  }, [targetRect]);
  return <div ref={ref} style={{ position: "absolute", top }}>{children}</div>;
}

function useCSS(rule) {
  useInsertionEffect(() => {
    const style = document.createElement("style");
    style.textContent = rule;
    document.head.appendChild(style);
    return () => style.remove();
  }, [rule]);
}

function Stopwatch() {
  const intervalRef = useRef(null);
  const inputRef = useRef(null);
  const [ms, setMs] = useState(0);
  const start = () => {
    intervalRef.current = setInterval(() => setMs(m => m + 10), 10);
  };
  const stop = () => clearInterval(intervalRef.current);
  return (
    <>
      <input ref={inputRef} />
      <button onClick={() => inputRef.current.focus()}>Focus</button>
      <button onClick={start}>Start</button><button onClick={stop}>Stop</button>
      <p>{ms} ms</p>
    </>
  );
}

function ClickTracker() {
  const [shown, setShown] = useState(0);   // displayed
