class ScrollingList extends React.Component {
  state = { prevItemsLength: 0, isNewItem: false };
  static getDerivedStateFromProps(props, state) {
    if (props.items.length !== state.prevItemsLength) {
      return { prevItemsLength: props.items.length, isNewItem: props.items.length >
        state.prevItemsLength };
    }
    return null;
  }
