function InfiniteFeed() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const sentinel = useRef(null);
  useEffect(() => {
    fetch(`/api/feed?page=${page}`).then(r => r.json()).then(data => {
      setItems(prev => [...prev, ...data.items]);
      setHasMore(data.hasMore);
    });
  }, [page]);
  useEffect(() => {
    if (!hasMore) return;
    const obs = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) setPage(p => p + 1);
    });
    obs.observe(sentinel.current);
    return () => obs.disconnect();
  }, [hasMore]);
  return <>{items.map(i => <Card key={i.id} item={i} />)}{hasMore && <div
    ref={sentinel}>Loading more...</div>}</>;
}

function Modal({ isOpen, onClose, title, children }) {
  useEffect(() => {
    if (!isOpen) return;
    const onKey = e => e.key === "Escape" && onClose();
    document.addEventListener("keydown", onKey);
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, [isOpen, onClose]);
  if (!isOpen) return null;
  return createPortal(
    <div className="overlay" onClick={onClose}>
      <div role="dialog" aria-modal="true" aria-labelledby="modal-title" className="modal"
        onClick={e => e.stopPropagation()}>
        <h2 id="modal-title">{title}</h2>
        {children}
        <button onClick={onClose}>Close</button>
      </div>
    </div>,
    document.body
  );
}

