function SelectAll({ items }) {
  const [selected, setSelected] = useState(new Set());
  const allRef = useRef(null);
  const all = selected.size === items.length && items.length > 0;
  const some = selected.size > 0 && !all;
  useEffect(() => { allRef.current.indeterminate = some; }, [some]);
  const toggleAll = () => setSelected(all ? new Set() : new Set(items.map(i => i.id)));
  const toggleOne = id => setSelected(prev => {
    const next = new Set(prev);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;                       // new Set so React sees a change
  });
  return (
    <>
      <label><input ref={allRef} type="checkbox" checked={all} onChange={toggleAll} /> Select
        all</label>
      {items.map(i => (
        <label key={i.id}>
          <input type="checkbox" checked={selected.has(i.id)} onChange={() => toggleOne(i.id)}
            /> {i.name}
        </label>
      ))}
    </>
  );
}

const ToastContext = createContext(null);
export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);
  const show = useCallback((message, type = "info") => {
    const id = crypto.randomUUID();
    setToasts(t => [...t, { id, message, type }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 3000);
  }, []);
  return (
    <ToastContext.Provider value={show}>
      {children}
      {createPortal(
        <div className="toast-container">
          {toasts.map(t => <div key={t.id} className={`toast ${t.type}`}>{t.message}</div>)}
        </div>,
        document.body
      )}
    </ToastContext.Provider>
  );
}
export const useToast = () => useContext(ToastContext);
function SaveButton() {
  const toast = useToast();
  return <button onClick={() => toast("Saved successfully", "success")}>Save</button>;
}

